// HSL RGB conversion
vec3 hsl2rgb(vec3 hsl) {
    float C = (1.0 - abs(2.0 * hsl.z - 1.0)) * hsl.y;
    float X = C * (1.0 - abs(mod(hsl.x * 6.0, 2.0) - 1.0));
    float m = hsl.z - 0.5 * C;
    vec3 rgb = hsl.x < 1.0/6.0 ? vec3(C, X, 0.0) :
               hsl.x < 2.0/6.0 ? vec3(X, C, 0.0) :
               hsl.x < 3.0/6.0 ? vec3(0.0, C, X) :
               hsl.x < 4.0/6.0 ? vec3(0.0, X, C) :
               hsl.x < 5.0/6.0 ? vec3(X, 0.0, C) : vec3(C, 0.0, X);
    return rgb + m;
}

float hash21(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
float lerp(float a, float b, float x) {return clamp((x - a) / (b - a), 0.0, 1.0);}
float sdBox( in vec2 p, in vec2 b ) // From Inigo Quilez https://iquilezles.org/articles/distfunctions2d/
{
    vec2 d = abs(p)-b;
    return length(max(d,0.0)) + min(max(d.x,d.y),0.0) - .08;
}
void mainImage( out vec4 o, in vec2 U )
{
    float t = iTime - 4.;
    vec2 R = iResolution.xy;
    float r = 9. + smoothstep(-.5, .5, sin(t*.4))*9.; // Number of rows
    vec2 s = floor(U/R.y*r);
    float p = tan(s.x*300.4+t*0.2)*0.4;
    vec2 u = fract(U/R.y*r-vec2(0., p));
    s.y = floor(U.y/R.y*r - p);
    vec3 a = vec3(fract(s.x*.43- s.y*.1*t*.2), 1.-abs(sin(s.y*0.1)*10.), .85),
         b = vec3(.0);
    vec2 pa = vec2(-.5, .0)+.5, pb = vec2(.5, .0)+.5;
    float ra = hash21(floor((U/R.y - vec2(0., p)/r)*R)/R);
    float n = 8., x = lerp(0., length(pb-pa), dot(u, pb-pa))+(ra-.5)/n; // n = number of colours
    vec3 c = smoothstep(50./R.y, 0.,
        sdBox(u-.5, vec2(.32)))*mix(hsl2rgb(a), hsl2rgb(b), (floor(x*n) + floor(x*n)/(n-1.))/n);
    o = vec4(c,1.0);
}
